29	/** Approved providers for discovery, with optional filters. */
30	export async function listApprovedProviders(
31	  filters: BrowseFilters = {},
32	): Promise<PublicProvider[]> {
33	  const supabase = await createClient();
34	  let query = supabase
35	    .from("providers")
36	    .select(PUBLIC_PROVIDER_COLUMNS)
37	    .eq("status", "approved");
38	
39	  if (filters.topic) query = query.contains("topics", [filters.topic]);
40	  if (filters.language) query = query.contains("languages", [filters.language]);
41	  if (filters.availableNow) query = query.eq("is_available_now", true);
42	  if (typeof filters.maxPriceCents === "number") {
43	    query = query.lte("price_block_30_cents", filters.maxPriceCents);
44	  }
45	
46	  const { data, error } = await query.order("rating_avg", { ascending: false });
47	  if (error) throw error;
48	  return (data ?? []) as unknown as PublicProvider[];
49	}
